        { id = 687, text = "Adventurers from all over sell things to Antonio-- come look for yourselves what little treasures he has for you this week." },
        { id = 688, text = "Travelers and adventurers make haste to the town circle and take advantage of Antonio's wonderful prices! Come one, come all!" },
