        { id = 690, text = "Leave your battles or errands, and browse my incredible wares! Only in Darkshire for a short time... praise the Light for that." },
        { id = 691, text = "Farewell, citizens of Darkshire. Until next time..." },
        { id = 692, text = "Finally, Redridge. A pleasant change from the dark, cold fog of Duskwood." },
        { id = 702, text = "Hello, hello, Amy. It's good to be back in Lakeshire and to see you, milady." },
        { id = 704, text = "Hear ye, hear ye! I'll pause to sell my wares for only a short time here in Lakeshire. Come to the town hall with haste!" },
        { id = 712, text = "I've finally reached Lakeshire-- come one, come all, and take advantage of Antonio Perelli's wonderful deals." },
        { id = 713, text = "Items powerful enough to help make the journey through Duskwood, Antonio Perelli's goods are now for sale here in Lakeshire." },
        { id = 714, text = "Good to see you again, Amy. Be safe, luv. I'm off to Goldshire now." },
        { id = 716, text = "Hello, my friends. It is good to see you again. Still keeping our borders free I see. Antonio appreciates your hard work." },
