        { id = 720, text = "Oh, I will, my friend. I will indeed. You, too, be safe." },
        { id = 721, text = "Wares for sale! Wares for sale! Come browse Antonio's wares before I must take my leave, citizens of Goldshire." },
        { id = 722, text = "Come one, come all! Antonio's wares are for sale. I may not return for a great deal of time, so come one, come all." },
        { id = 723, text = "Good people of Goldshire, come take advantage of my incredible prices on rare goods. I shall not return for some time!" },
        { id = 724, text = "Good bye, Goldshire. I'll be back soon enough-- perhaps a week's time." },
        { id = 725, text = "Home again, home again." },
        { id = 726, text = "Known throughout the lands, Antonio Perelli's goods now for sale near Sentinel Hill! I must move on soon, so make haste." },
