    [3513] = { name = "Miss Danna",
        { id = 1129, text = "Here we have the Cathedral of Light, the center of spiritual enlightenment here in Stormwind." },
        { id = 1140, text = "Here we have Stormwind Keep. Built upon the ruins of Stormwind Castle, which was destroyed by the Horde in the first Great War." },
        { id = 1154, text = "Yes, that is true. Paladins and priests alike train their skills and research great truths behind the walls of the Cathedral." },
        { id = 1155, text = "Children if you would please follow me, we will now be going to see the keep where King Anduin Wrynn himself sits on his throne." },
        { id = 1161, text = "When the Horde was shattered, men returned here and began to rebuild the once great city as a testament to our own survival." },
        { id = 1162, text = "Yes, well...let's head on to the monument dedicated to the heroes of the two Great Wars, the Valley of Heroes. Follow me." },
        { id = 1163, text = "Isn't it amazing, children? All who enter the city must walk beneath the watchful eyes of the greatest heroes of our lands." },
        { id = 1165, text = "Breathtaking. Children, when we return to the school, you will each give an oral report on one of these legendary people." },
        { id = 1166, text = "Now, take another long look before we make our way to the Holy District and the great Cathedral of Light." },
    },
