        { id = 10128, text = "The longer you wait, the less future you have for me to foretell." },
    },
    [14823] = { name = "Silas Darkmoon",
        { id = 10153, text = "Everyone enjoying themselves so far? That's great! Welcome to the Darkmoon Faire, the greatest show on all of Azeroth! Make sure that you speak with Yebb and his friends here while you're taking in Neblegear's Darkmoon Zoo Bizarre." },
        { id = 10154, text = "Come one, come all. Welcome to the Darkmoon Faire! Don't be shy. Step right up to Lhara and buy yourself an exotic artifact from far off lands. If you're one of the lucky few who have found Darkmoon Cards, have a word with Professor Paleo. Hungry? Thirsty? You're in luck! Refreshments are available right here from Sylannia and Stamp. I recommend the Darkmoon Special Reserve to wash down some Red Hot Wings. And if the future is what you seek, then run, don't walk, to speak with Sayge." },
        { id = 10155, text = "Welcome one and all to the Darkmoon Faire, the greatest event in all the world! We have it all... delicious food, strong drink, exotic artifacts, fortunes read, amazing prizes and excitement without end! Don't forget to turn in your Darkmoon Faire Prize Tickets to Gelvas Grimegate! All it takes is five or more and you're on your way to the most wondrous prizes on all of Azeroth. Everybody is a winner!" },
        { id = 10156, text = "Welcome one and all to the greatest show on all of Azeroth... the Darkmoon Faire! Adventure and excitement await, don't be shy! Mysteries and prizes for both the young and the old are here for the taking. And be sure to speak with the professor about any Darkmoon Cards that you have come across during your travels!" },
        { id = 10157, text = "Greetings friends, and welcome to the greatest show on Azeroth!$B$BPlease, step right up and take in all we have to offer. Ride the rides and see the sights! Amaze at the wonders that the Darkmoon Faire has uncovered in this vast and mysterious world! We have spared no expense in bringing you excitement that children of all ages will delight in!" },
        { id = 10158, text = "Come one, come all! Welcome to the Darkmoon Faire! Do you crave adventure? Do you seek exotic and mysterious treasures? Then look no further! You, my friend, have come to the right place! Dive right in and take part in all that the Faire has to offer! We'll be at this location all week, so be sure to tell your friends and loved ones!" },
        { id = 10160, text = "We're back and better than ever! It's the Darkmoon Faire friend, and it's your lucky day! Sparing no expense, we've gathered wonders and treats from around the world for your delight. Whether you're young or old, rich or poor, the Darkmoon Faire has it all! Be sure to turn in your Darkmoon Faire Prize Tickets to Gelvas Grimegate, and choose from several exotic and wondrous prizes!" },
    },
    [14828] = { name = "Gelvas Grimegate",
        { id = 10149, text = "Tickets! Redeem your Darkmoon Faire Prize Tickets here! Wondrous and exotic prizes are waiting for you!" },
        { id = 10150, text = "Mysterious prizes await the adventurous. Step right up, step right up!" },
        { id = 10151, text = "Five tickets or two-hundred and fifty, it doesn't matter friend, everybody is a winner!" },
        { id = 10152, text = "Prizes! Get your prizes right here! Get over here and turn in your Darkmoon Faire Prize Tickets for valuable prizes!" },
    },
