    [14846] = { name = "Lhara",
        { id = 10141, text = "Every item that I have for sale I acquired myself. You have my personal guarantee of authenticity." },
        { id = 10142, text = "Darkmoon Faire Cards? See the Professor here for those. Come see me if you are a dealer in hard to come by antiquities and artifacts." },
        { id = 10143, text = "Come and take a look at my wares while you still can. We're here all week, and then we're off to some far off land." },
        { id = 10144, text = "Have you any idea what I go through to bring these incomparable valuables to sell? Come see them all for yourself!" },
    },
    [14847] = { name = "Professor Thaddeus Paleo",
        { id = 10137, text = "I have a fine selection of exotic potions and scrolls. But they're not for the faint of heart!" },
        { id = 10138, text = "Come speak with me if you are a purveyor of the unusual, or if you have any Darkmoon Faire Cards." },
        { id = 10139, text = "If you wait to come see me, there may be nothing left!" },
        { id = 10140, text = "Have you any Darkmoon Faire cards? Come speak with me to learn more about them if you dare!" },
    },
    [14849] = { name = "Darkmoon Faire Carnie",
        { id = 10058, text = "Can't you see I've got work to do here?" },
        { id = 10059, text = "Faire's a coming!" },
        { id = 10060, text = "That's right friend! The Darkmoon Faire is going to be right here. Just as soon as I unload those huge wagons, put up all the tents, erect the zoo and pour the drinks. Make sure you come back!" },
        { id = 10061, text = "Won't be long now until the Darkmoon Faire opens. Come back later and check to see if we're done." },
        { id = 10118, text = "Sure are a lot of litter bugs around here." },
        { id = 10119, text = "Having a good time?" },
        { id = 10120, text = "Don't forget to buy refreshments and souvenirs!" },
        { id = 10121, text = "The Darkmoon Faire is the greatest event on all of Azeroth!" },
    },
